(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-236":{scenario:{company:"Đại Lộc Precision Manufacturing",supervisor:{name:"Nguyễn Hoài Nam",role:{vi:"Trưởng phòng Mua hàng",en:"Procurement Manager"}},ref_code:"RFQ-2419",title:{vi:"Đúng nhà cung cấp. Đúng tổng chi phí.",en:"Right supplier. Right total cost."},brief:{vi:"Bạn chấm RFQ-2419 mua 5000 vỏ ổ bi gang. Báo giá: V-118 41000 đ/cái, đã gồm vận chuyển; V-204 42500 đ/cái, vận chuyển 6 triệu đ/lô; V-377 40200 đ/cái, phí làm khuôn một lần 18 triệu đ, vận chuyển 4 triệu đ. Chất lượng và tiến độ ba bên tương đương. Đối chiếu đề xuất nháp với hồ sơ đã duyệt, sửa nhà cung cấp trúng chọn và tổng chi phí (VND, số liệu mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are evaluating RFQ-2419 for 5000 cast iron bearing housings. Quotes: V-118 41000 VND each, freight included; V-204 42500 VND each, freight 6 million VND per lot; V-377 40200 VND each, one-off tooling 18 million VND, freight 4 million VND. Quality and lead time are equivalent. Compare the draft recommendation with the approved file, correct the awarded supplier and the total cost (VND, simulated figures), then write an evidence-based report."},reference_title:{vi:"Hồ sơ đánh giá báo giá & AVL đã duyệt · RFQ-2419",en:"Approved bid evaluation & AVL file · RFQ-2419"},fields:[{id:"SUPPLIER",label:{vi:"Nhà cung cấp trúng chọn",en:"Awarded supplier"},initial:"V-377",expected:"V-204",choices:["V-118","V-204","V-377"],reference:"Danh sách nhà cung cấp được duyệt",ref_value:{vi:"AVL: V-204, V-377 còn hiệu lực; V-118 quá hạn đánh giá lại, tạm ngừng giao dịch",en:"AVL: V-204, V-377 valid; V-118 overdue for re-audit, suspended"},hint:{vi:"Chỉ chọn trong AVL, rồi so tổng chi phí sở hữu chứ không so đơn giá.",en:"Choose only from the AVL, then compare total cost of ownership rather than unit price."}},{id:"TCO_VND",label:{vi:"Tổng chi phí phương án chọn (VND)",en:"Total cost of the award (VND)"},initial:"201000000",expected:"218500000",reference:"Bảng so sánh tổng chi phí",ref_value:{vi:"Số lượng 5000 cái; cộng phí khuôn, vận chuyển vào giá hàng của từng nhà cung cấp",en:"Quantity 5000 pcs; add tooling and freight to each supplier's goods value"},hint:{vi:"Tổng chi phí = đơn giá x số lượng + chi phí một lần + vận chuyển; tính cho cả hai nhà cung cấp hợp lệ.",en:"Total cost = unit price x quantity + one-off costs + freight; compute it for both eligible suppliers."}}],sop32:{vi:"Tổng chi phí sở hữu = đơn giá x số lượng + chi phí một lần (khuôn, thử mẫu) + vận chuyển; chọn nhà cung cấp trong AVL có tổng chi phí thấp nhất khi chất lượng, tiến độ tương đương.",en:"Total cost of ownership = unit price x quantity + one-off costs (tooling, samples) + freight; award the AVL supplier with the lowest total when quality and lead time are equal."},context:{label:"e-Procurement / RFQ-2419",metrics:[{label:{vi:"Số lượng (cái)",en:"Quantity (pcs)"},value:"5,000"},{label:{vi:"Số báo giá nhận được",en:"Quotes received"},value:"3"},{label:{vi:"Ngưỡng trình Tổng giám đốc (VND)",en:"CEO approval threshold (VND)"},value:"100,000,000"}]},crisis:{vi:"Giám đốc xưởng nhắn: “Chọn V-118 đi, chỗ người quen của anh. Cứ tách thành 3 đơn dưới 100 triệu để khỏi trình Tổng giám đốc, AVL tính sau.”",en:"The plant manager messages you: “Pick V-118, they are my acquaintances. Split it into 3 orders under 100 million so it skips the CEO, and sort out the AVL later.”"},options:{safe:{vi:"Từ chối tách đơn và mua ngoài AVL; báo Trưởng phòng Mua hàng về xung đột lợi ích, trình duyệt V-204 đúng ma trận phân quyền; nếu muốn dùng V-118 thì đề nghị đánh giá lại trước.",en:"Refuse to split the order or buy outside the AVL; report the conflict of interest to the procurement manager, route V-204 through the approval matrix, and require a re-audit before V-118 is used."},shortcut:{vi:"Chọn V-118 và tách thành 3 đơn dưới 100 triệu đ theo ý giám đốc xưởng.",en:"Award V-118 and split it into 3 orders under 100 million VND as the plant manager wants."},wait:{vi:"Treo hồ sơ RFQ, không trình ai để giám đốc xưởng tự quyết.",en:"Park the RFQ file and escalate nothing, leaving the plant manager to decide."}},questions:{vi:["Vì sao trao thầu cho V-204 thay vì V-377 có đơn giá thấp nhất? Bảng tổng chi phí nào chứng minh?","Trình bày cách tính tổng chi phí sở hữu và rủi ro tuân thủ khi tách đơn hoặc mua từ nhà cung cấp ngoài AVL."],en:["Why award V-204 instead of V-377, which has the lowest unit price? Which total cost table proves it?","Explain how you calculated total cost of ownership and the compliance risks of splitting orders or buying outside the AVL."]},hints:{vi:["Đặt đề xuất nháp cạnh danh sách AVL, loại nhà cung cấp không còn hiệu lực trước khi so giá.","Cộng đơn giá x số lượng, phí khuôn và vận chuyển cho từng nhà cung cấp theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không tách đơn để né phân quyền phê duyệt; xung đột lợi ích phải khai báo."],en:["Place the draft next to the AVL and remove suppliers that are no longer valid before comparing prices.","Add unit price x quantity, tooling and freight for each supplier per SOP 3.2.","Re-read SOP 4.2: never split orders to avoid approval limits; conflicts of interest must be declared."]}},learning:{summary:{vi:"Chuyên viên mua hàng và quản lý nhà cung cấp tìm nguồn, mời báo giá, đánh giá và lựa chọn nhà cung cấp, đàm phán hợp đồng, phát hành đơn mua và theo dõi hiệu suất giao hàng, chất lượng. Mục tiêu là mua đúng chất lượng, đúng thời điểm với tổng chi phí sở hữu tối ưu, đồng thời bảo đảm minh bạch, đúng phân quyền và không có xung đột lợi ích.",en:"A procurement and vendor management specialist sources suppliers, runs RFQs, evaluates and selects vendors, negotiates contracts, issues purchase orders and tracks delivery and quality performance. The aim is to buy the right quality at the right time at the best total cost of ownership while staying transparent, within approval limits and free of conflicts of interest."},responsibilities:{vi:["Tìm nguồn, mời báo giá (RFQ) và đánh giá năng lực nhà cung cấp mới.","So sánh báo giá theo tổng chi phí sở hữu, tiêu chí kỹ thuật và trình duyệt theo ma trận phân quyền.","Đàm phán giá, điều khoản thanh toán, giao hàng, bảo hành và soạn hợp đồng mua bán.","Phát hành đơn mua, theo dõi tiến độ giao hàng và phối hợp kiểm tra chất lượng đầu vào.","Đánh giá định kỳ nhà cung cấp, cập nhật danh sách AVL và quản lý rủi ro nguồn cung."],en:["Source suppliers, issue RFQs and assess the capability of new vendors.","Compare bids on total cost of ownership and technical criteria and route approvals through the authority matrix.","Negotiate price, payment, delivery and warranty terms and draft purchase contracts.","Issue purchase orders, expedite deliveries and coordinate incoming quality checks.","Review suppliers periodically, maintain the AVL and manage supply risk."]},competencies:[{name:{vi:"Tìm nguồn chiến lược",en:"Strategic sourcing"},desc:{vi:"Phân tích thị trường cung, phân nhóm vật tư theo ma trận Kraljic và chọn chiến lược mua phù hợp.",en:"Analyze supply markets, segment categories with the Kraljic matrix and choose the right sourcing strategy."}},{name:{vi:"Phân tích tổng chi phí",en:"Total cost analysis"},desc:{vi:"Tính TCO gồm giá, khuôn, vận chuyển, chất lượng, tồn kho để so sánh công bằng.",en:"Build TCO including price, tooling, freight, quality and inventory for a fair comparison."}},{name:{vi:"Đàm phán hợp đồng",en:"Contract negotiation"},desc:{vi:"Thương lượng giá và điều khoản rủi ro như phạt chậm giao, bảo hành có lợi cho doanh nghiệp.",en:"Negotiate price and risk terms such as late delivery penalties and warranties in the company's favour."}},{name:{vi:"Quản lý hiệu suất nhà cung cấp",en:"Supplier performance management"},desc:{vi:"Đo OTIF, tỷ lệ lỗi, tốc độ phản hồi và dẫn dắt cải tiến với nhà cung cấp.",en:"Measure OTIF, defect rates and responsiveness and drive improvement with suppliers."}},{name:{vi:"Liêm chính mua hàng",en:"Procurement integrity"},desc:{vi:"Khai báo xung đột lợi ích, tuân thủ phân quyền, từ chối quà tặng và lợi ích không chính đáng.",en:"Declare conflicts of interest, respect approval limits and refuse improper gifts or benefits."}}],knowledge:{vi:["ISO 9001:2015 điều 8.4 về kiểm soát quá trình, sản phẩm và dịch vụ do bên ngoài cung cấp.","Luật Thương mại 2005 (số 36/2005/QH11) và Bộ luật Dân sự 2015 (số 91/2015/QH13) về hợp đồng mua bán hàng hóa.","Luật Đấu thầu 2023 (số 22/2023/QH15) cho mua sắm sử dụng vốn nhà nước; doanh nghiệp tư nhân tham chiếu nguyên tắc cạnh tranh, minh bạch.","ISO 20400:2017 về mua sắm bền vững và đánh giá nhà cung cấp theo tiêu chí môi trường, xã hội.","Kiểm soát nội bộ trong mua hàng: phân quyền phê duyệt, tách bạch nhiệm vụ, đối chiếu ba bên đơn mua, phiếu nhập, hóa đơn."],en:["ISO 9001:2015 clause 8.4 on control of externally provided processes, products and services.","Commercial Law 2005 (No. 36/2005/QH11) and Civil Code 2015 (No. 91/2015/QH13) on sales contracts.","Bidding Law 2023 (No. 22/2023/QH15) for state-funded procurement; private firms follow its principles of competition and transparency.","ISO 20400:2017 on sustainable procurement and supplier assessment against environmental and social criteria.","Purchasing internal controls: approval authority, segregation of duties and three-way match of PO, goods receipt and invoice."]},tools:["Hệ thống mua hàng điện tử (e-Procurement)","Mô-đun mua hàng của ERP","Bảng so sánh báo giá và TCO","Phiếu đánh giá nhà cung cấp (scorecard)","Hệ thống quản lý hợp đồng"],kpis:{vi:["Mức tiết kiệm chi phí so với ngân sách hoặc giá cơ sở.","Tỷ lệ giao hàng đúng hạn, đủ số lượng (OTIF) của nhà cung cấp.","Tỷ lệ chi tiêu qua nhà cung cấp trong AVL và có hợp đồng.","Thời gian từ yêu cầu mua đến phát hành đơn mua."],en:["Cost savings against budget or baseline price.","Supplier on-time in-full (OTIF) delivery rate.","Share of spend with AVL suppliers under contract.","Cycle time from purchase requisition to purchase order."]},day:[{time:"08:00",vi:"Rà soát yêu cầu mua mới, kiểm tra ngân sách, quy cách kỹ thuật và mức độ khẩn.",en:"Review new requisitions and check budget, specifications and urgency."},{time:"09:30",vi:"Gửi RFQ, trao đổi kỹ thuật với nhà cung cấp và làm rõ điều khoản báo giá.",en:"Send RFQs, discuss technical points with suppliers and clarify quote terms."},{time:"13:30",vi:"Lập bảng so sánh tổng chi phí, trình duyệt theo ma trận phân quyền.",en:"Build the total cost comparison and route it through the approval matrix."},{time:"15:30",vi:"Đàm phán hợp đồng, đôn đốc đơn mua trễ hạn và xử lý hàng lỗi với QC.",en:"Negotiate contracts, chase late orders and resolve defects with QC."},{time:"17:00",vi:"Cập nhật scorecard nhà cung cấp, AVL và báo cáo tiết kiệm chi phí.",en:"Update supplier scorecards and the AVL and report cost savings."}],mistakes:{vi:["Chọn nhà cung cấp theo đơn giá thấp nhất mà bỏ qua chi phí khuôn, vận chuyển, chất lượng.","Phát hành đơn mua cho nhà cung cấp ngoài AVL hoặc đã quá hạn đánh giá lại.","Tách nhỏ đơn mua để né ngưỡng phê duyệt hoặc ưu ái người quen, vi phạm kiểm soát nội bộ."],en:["Choosing the lowest unit price while ignoring tooling, freight and quality costs.","Issuing POs to suppliers outside the AVL or overdue for re-audit.","Splitting orders to dodge approval limits or to favour acquaintances, breaching internal controls."]},career:[{vi:"Nhân viên mua hàng",en:"Purchasing assistant"},{vi:"Chuyên viên mua hàng & quản lý nhà cung cấp",en:"Procurement & vendor management specialist"},{vi:"Trưởng nhóm tìm nguồn chiến lược",en:"Strategic sourcing lead"},{vi:"Giám đốc mua hàng",en:"Chief procurement officer"}],glossary:[{term:"RFQ",vi:"Yêu cầu báo giá gửi nhiều nhà cung cấp với cùng quy cách, số lượng và điều kiện.",en:"Request for quotation sent to several suppliers with the same specification, quantity and terms."},{term:"AVL",vi:"Danh sách nhà cung cấp được phê duyệt sau đánh giá năng lực, chất lượng.",en:"Approved vendor list of suppliers qualified after capability and quality assessment."},{term:"TCO",vi:"Tổng chi phí sở hữu: giá mua cộng mọi chi phí phát sinh trong vòng đời mua và sử dụng.",en:"Total cost of ownership: purchase price plus all costs over the buying and usage life cycle."},{term:"Three-way match",vi:"Đối chiếu ba bên giữa đơn mua, phiếu nhập kho và hóa đơn trước khi thanh toán.",en:"Matching the purchase order, goods receipt and invoice before payment."},{term:"DOA",vi:"Ma trận phân quyền phê duyệt theo giá trị và loại giao dịch.",en:"Delegation of authority matrix setting approval rights by value and transaction type."}],quiz:[{q:{vi:"NCC A: 100000 đ/cái x 1000 cái, vận chuyển 5 triệu đ. NCC B: 97000 đ/cái, phí khuôn 6 triệu đ, vận chuyển 3 triệu đ. Phương án nào rẻ hơn về tổng chi phí?",en:"Supplier A: 100000 VND each x 1000 pcs, freight 5 million VND. Supplier B: 97000 VND each, tooling 6 million VND, freight 3 million VND. Which is cheaper in total?"},options:{vi:["NCC B, vì đơn giá thấp hơn","Hai phương án bằng nhau","NCC A, rẻ hơn 1 triệu đ","Không đủ dữ liệu"],en:["Supplier B, because its unit price is lower","Both are equal","Supplier A, cheaper by 1 million VND","Not enough data"]},answer:2,explain:{vi:"A = 100 + 5 = 105 triệu đ; B = 97 + 6 + 3 = 106 triệu đ, nên A rẻ hơn 1 triệu đ.",en:"A = 100 + 5 = 105 million VND; B = 97 + 6 + 3 = 106 million VND, so A is cheaper by 1 million."}},{q:{vi:"Đối chiếu ba bên (three-way match) là gì?",en:"What is a three-way match?"},options:{vi:["Khớp đơn mua, phiếu nhập kho và hóa đơn trước khi thanh toán","So sánh ba báo giá","Ba người cùng ký hợp đồng","Kiểm tra ba lô hàng mẫu"],en:["Matching PO, goods receipt and invoice before payment","Comparing three quotes","Three people signing the contract","Inspecting three sample lots"]},answer:0,explain:{vi:"Ba chứng từ phải khớp về số lượng, đơn giá trước khi thanh toán để ngăn sai sót và gian lận.",en:"The three documents must agree on quantity and price before payment to prevent errors and fraud."}},{q:{vi:"Người đề nghị mua muốn tách đơn để dưới ngưỡng duyệt của Tổng giám đốc. Bạn làm gì?",en:"A requester wants to split an order to stay below the CEO approval limit. What do you do?"},options:{vi:["Đồng ý vì vẫn mua đúng hàng","Từ chối, gộp đúng nhu cầu và trình duyệt theo ma trận phân quyền","Tách đơn nhưng ghi chú lại","Chuyển cho kế toán quyết định"],en:["Agree since the goods are right","Refuse, consolidate the real need and route it through the approval matrix","Split it but add a note","Let accounting decide"]},answer:1,explain:{vi:"Tách đơn để né phê duyệt là vi phạm kiểm soát nội bộ; nhu cầu thực phải được trình đúng cấp.",en:"Splitting to avoid approval breaches internal control; the real need must go to the right authority."}},{q:{vi:"Điều khoản nào hướng dẫn kiểm soát sản phẩm, dịch vụ do bên ngoài cung cấp trong hệ thống quản lý chất lượng?",en:"Which clause covers control of externally provided products and services in a quality management system?"},options:{vi:["ISO 14001 điều 6.1","ISO 45001 điều 5.4","ISO/IEC 27001 phụ lục A","ISO 9001:2015 điều 8.4"],en:["ISO 14001 clause 6.1","ISO 45001 clause 5.4","ISO/IEC 27001 Annex A","ISO 9001:2015 clause 8.4"]},answer:3,explain:{vi:"ISO 9001:2015 điều 8.4 yêu cầu đánh giá, lựa chọn, theo dõi và đánh giá lại nhà cung cấp bên ngoài.",en:"ISO 9001:2015 clause 8.4 requires evaluating, selecting, monitoring and re-evaluating external providers."}}],tools_en:["E-procurement system","ERP purchasing module","Quote comparison and TCO analysis sheet","Supplier evaluation scorecard","Contract management system"]}}})})(window.KKR);
